-- Reviewed catalogs, original identities and explicitly approved 6-stamp/10-percent loyalty
BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='60s';
CREATE TEMP TABLE dabab_before ON COMMIT DROP AS SELECT jsonb_build_object('subscriptions',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.subscriptions t ),'loyalty_cards',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.loyalty_cards t ),'offers',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.offers t ),'cafes',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.cafes t ),'brand_feature_overrides',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.brand_feature_overrides t ),'menu_products',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.menu_products t WHERE cafe_id NOT IN('3813425d-db13-4d30-8b82-9d41aad12e36')),'menu_categories',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.menu_categories t WHERE cafe_id NOT IN('3813425d-db13-4d30-8b82-9d41aad12e36')),'cafe_settings',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY cafe_id)::text,'')) FROM public.cafe_settings t WHERE cafe_id NOT IN('3813425d-db13-4d30-8b82-9d41aad12e36')),'cafe_custom_identity',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY cafe_id)::text,'')) FROM public.cafe_custom_identity t WHERE cafe_id NOT IN('3813425d-db13-4d30-8b82-9d41aad12e36')),'cafe_loyalty_programs',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY cafe_id)::text,'')) FROM public.cafe_loyalty_programs t WHERE cafe_id NOT IN('3813425d-db13-4d30-8b82-9d41aad12e36')),'cafe_loyalty_experience',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY cafe_id)::text,'')) FROM public.cafe_loyalty_experience t WHERE cafe_id NOT IN('3813425d-db13-4d30-8b82-9d41aad12e36'))) snapshot;
CREATE TEMP TABLE dabab_settings_before ON COMMIT DROP AS SELECT cafe_id,to_jsonb(s)-'logo_storage_path'-'updated_at' payload FROM public.cafe_settings s WHERE cafe_id IN('3813425d-db13-4d30-8b82-9d41aad12e36');
DO $brand$ BEGIN PERFORM 1 FROM public.cafes WHERE id='3813425d-db13-4d30-8b82-9d41aad12e36' AND slug='brand-8ad185ee82e3' AND status='active' AND is_public AND deleted_at IS NULL FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Brand identity changed';END IF; IF NOT platform_access_private.service_enabled('3813425d-db13-4d30-8b82-9d41aad12e36','menu') OR NOT platform_access_private.service_enabled('3813425d-db13-4d30-8b82-9d41aad12e36','loyalty') THEN RAISE EXCEPTION 'Existing subscription does not permit menu and loyalty';END IF; END $brand$;
CREATE TEMP TABLE dabab_expected_categories ON COMMIT DROP AS SELECT * FROM public.menu_categories WITH NO DATA;
DO $guard$ BEGIN IF EXISTS(SELECT 1 FROM public.menu_categories WHERE cafe_id='3813425d-db13-4d30-8b82-9d41aad12e36') AND (EXISTS(SELECT id,cafe_id,branch_id,name,description,sort_order,visible FROM public.menu_categories WHERE cafe_id='3813425d-db13-4d30-8b82-9d41aad12e36' EXCEPT SELECT id,cafe_id,branch_id,name,description,sort_order,visible FROM dabab_expected_categories WHERE cafe_id='3813425d-db13-4d30-8b82-9d41aad12e36') OR EXISTS(SELECT id,cafe_id,branch_id,name,description,sort_order,visible FROM dabab_expected_categories WHERE cafe_id='3813425d-db13-4d30-8b82-9d41aad12e36' EXCEPT SELECT id,cafe_id,branch_id,name,description,sort_order,visible FROM public.menu_categories WHERE cafe_id='3813425d-db13-4d30-8b82-9d41aad12e36')) THEN RAISE EXCEPTION 'Existing categories differ; preserve owner changes'; END IF; END $guard$;
CREATE TEMP TABLE dabab_expected_products ON COMMIT DROP AS SELECT * FROM public.menu_products WITH NO DATA;
بارد: 19 ر.س',19,'{19}',NULL,16,true,'product',NULL,'{}','{"options":[{"id":"variant-1","label":"حار","price":19,"available":true},{"id":"variant-2","label":"بارد","price":19,"available":true}]}'::jsonb);
بارد: 19 ر.س',19,'{19}',NULL,17,true,'product',NULL,'{}','{"options":[{"id":"variant-1","label":"حار","price":19,"available":true},{"id":"variant-2","label":"بارد","price":19,"available":true}]}'::jsonb);
بارد: 19 ر.س',19,'{19}',NULL,18,true,'product',NULL,'{}','{"options":[{"id":"variant-1","label":"حار","price":19,"available":true},{"id":"variant-2","label":"بارد","price":19,"available":true}]}'::jsonb);
بارد: 23 ر.س',23,'{23}',NULL,19,true,'product',NULL,'{}','{"options":[{"id":"variant-1","label":"حار","price":23,"available":true},{"id":"variant-2","label":"بارد","price":23,"available":true}]}'::jsonb);
DO $guard$ BEGIN IF EXISTS(SELECT 1 FROM public.menu_products WHERE cafe_id='3813425d-db13-4d30-8b82-9d41aad12e36') AND (EXISTS(SELECT id,cafe_id,branch_id,category_id,name,description,price,price_options,calories,sort_order,available,catalog_kind,image_storage_path,gallery_storage_paths,commerce_details FROM public.menu_products WHERE cafe_id='3813425d-db13-4d30-8b82-9d41aad12e36' EXCEPT SELECT id,cafe_id,branch_id,category_id,name,description,price,price_options,calories,sort_order,available,catalog_kind,image_storage_path,gallery_storage_paths,commerce_details FROM dabab_expected_products WHERE cafe_id='3813425d-db13-4d30-8b82-9d41aad12e36') OR EXISTS(SELECT id,cafe_id,branch_id,category_id,name,description,price,price_options,calories,sort_order,available,catalog_kind,image_storage_path,gallery_storage_paths,commerce_details FROM dabab_expected_products WHERE cafe_id='3813425d-db13-4d30-8b82-9d41aad12e36' EXCEPT SELECT id,cafe_id,branch_id,category_id,name,description,price,price_options,calories,sort_order,available,catalog_kind,image_storage_path,gallery_storage_paths,commerce_details FROM public.menu_products WHERE cafe_id='3813425d-db13-4d30-8b82-9d41aad12e36')) THEN RAISE EXCEPTION 'Existing products differ; preserve owner changes'; END IF; END $guard$;
CREATE TEMP TABLE dabab_expected_programs ON COMMIT DROP AS SELECT * FROM public.cafe_loyalty_programs WITH NO DATA;
DO $guard$ BEGIN IF EXISTS(SELECT 1 FROM public.cafe_loyalty_programs WHERE cafe_id='3813425d-db13-4d30-8b82-9d41aad12e36') AND (EXISTS(SELECT cafe_id,enabled,purchases_required,reward_product_id,reward_name,card_title,card_subtitle,stamp_label,terms,card_background,card_foreground,card_accent,wallet_enabled,apple_wallet_enabled,google_wallet_enabled,card_design FROM public.cafe_loyalty_programs WHERE cafe_id='3813425d-db13-4d30-8b82-9d41aad12e36' EXCEPT SELECT cafe_id,enabled,purchases_required,reward_product_id,reward_name,card_title,card_subtitle,stamp_label,terms,card_background,card_foreground,card_accent,wallet_enabled,apple_wallet_enabled,google_wallet_enabled,card_design FROM dabab_expected_programs WHERE cafe_id='3813425d-db13-4d30-8b82-9d41aad12e36') OR EXISTS(SELECT cafe_id,enabled,purchases_required,reward_product_id,reward_name,card_title,card_subtitle,stamp_label,terms,card_background,card_foreground,card_accent,wallet_enabled,apple_wallet_enabled,google_wallet_enabled,card_design FROM dabab_expected_programs WHERE cafe_id='3813425d-db13-4d30-8b82-9d41aad12e36' EXCEPT SELECT cafe_id,enabled,purchases_required,reward_product_id,reward_name,card_title,card_subtitle,stamp_label,terms,card_background,card_foreground,card_accent,wallet_enabled,apple_wallet_enabled,google_wallet_enabled,card_design FROM public.cafe_loyalty_programs WHERE cafe_id='3813425d-db13-4d30-8b82-9d41aad12e36')) THEN RAISE EXCEPTION 'Existing programs differ; preserve owner changes'; END IF; END $guard$;
CREATE TEMP TABLE dabab_expected_experiences ON COMMIT DROP AS SELECT * FROM public.cafe_loyalty_experience WITH NO DATA;
DO $guard$ BEGIN IF EXISTS(SELECT 1 FROM public.cafe_loyalty_experience WHERE cafe_id='3813425d-db13-4d30-8b82-9d41aad12e36') AND (EXISTS(SELECT cafe_id,reward_kind,reward_discount_percent,nearby_message FROM public.cafe_loyalty_experience WHERE cafe_id='3813425d-db13-4d30-8b82-9d41aad12e36' EXCEPT SELECT cafe_id,reward_kind,reward_discount_percent,nearby_message FROM dabab_expected_experiences WHERE cafe_id='3813425d-db13-4d30-8b82-9d41aad12e36') OR EXISTS(SELECT cafe_id,reward_kind,reward_discount_percent,nearby_message FROM dabab_expected_experiences WHERE cafe_id='3813425d-db13-4d30-8b82-9d41aad12e36' EXCEPT SELECT cafe_id,reward_kind,reward_discount_percent,nearby_message FROM public.cafe_loyalty_experience WHERE cafe_id='3813425d-db13-4d30-8b82-9d41aad12e36')) THEN RAISE EXCEPTION 'Existing experiences differ; preserve owner changes'; END IF; END $guard$;
DO $logo$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.cafe_settings WHERE cafe_id='3813425d-db13-4d30-8b82-9d41aad12e36') THEN RAISE EXCEPTION 'Brand settings missing';END IF; IF EXISTS(SELECT 1 FROM public.cafe_settings WHERE cafe_id='3813425d-db13-4d30-8b82-9d41aad12e36' AND ((logo_storage_path IS NOT NULL AND logo_storage_path IS DISTINCT FROM '3813425d-db13-4d30-8b82-9d41aad12e36/identity/dabab-20261104-889840eb6f898b6e.webp') OR logo_url IS NOT NULL)) OR EXISTS(SELECT 1 FROM public.cafe_custom_identity WHERE cafe_id='3813425d-db13-4d30-8b82-9d41aad12e36' AND (logo_storage_path IS DISTINCT FROM '3813425d-db13-4d30-8b82-9d41aad12e36/identity/dabab-20261104-889840eb6f898b6e.webp' OR logo_url IS NOT NULL OR palette IS DISTINCT FROM '{"primary":"#134b3d","secondary":"#376958","accent":"#e5ebd8","background":"#134b3d","text":"#ffffff","button":"#134b3d"}'::jsonb)) THEN RAISE EXCEPTION 'Existing identity differs; preserve owner changes';END IF; END $logo$;
UPDATE public.cafe_settings SET logo_storage_path='3813425d-db13-4d30-8b82-9d41aad12e36/identity/dabab-20261104-889840eb6f898b6e.webp',updated_at=now() WHERE cafe_id='3813425d-db13-4d30-8b82-9d41aad12e36' AND logo_storage_path IS DISTINCT FROM '3813425d-db13-4d30-8b82-9d41aad12e36/identity/dabab-20261104-889840eb6f898b6e.webp';
DO $verify$ DECLARE actual jsonb;BEGIN SELECT jsonb_build_object('subscriptions',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.subscriptions t ),'loyalty_cards',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.loyalty_cards t ),'offers',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.offers t ),'cafes',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.cafes t ),'brand_feature_overrides',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.brand_feature_overrides t ),'menu_products',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.menu_products t WHERE cafe_id NOT IN('3813425d-db13-4d30-8b82-9d41aad12e36')),'menu_categories',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.menu_categories t WHERE cafe_id NOT IN('3813425d-db13-4d30-8b82-9d41aad12e36')),'cafe_settings',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY cafe_id)::text,'')) FROM public.cafe_settings t WHERE cafe_id NOT IN('3813425d-db13-4d30-8b82-9d41aad12e36')),'cafe_custom_identity',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY cafe_id)::text,'')) FROM public.cafe_custom_identity t WHERE cafe_id NOT IN('3813425d-db13-4d30-8b82-9d41aad12e36')),'cafe_loyalty_programs',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY cafe_id)::text,'')) FROM public.cafe_loyalty_programs t WHERE cafe_id NOT IN('3813425d-db13-4d30-8b82-9d41aad12e36')),'cafe_loyalty_experience',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY cafe_id)::text,'')) FROM public.cafe_loyalty_experience t WHERE cafe_id NOT IN('3813425d-db13-4d30-8b82-9d41aad12e36'))) INTO actual; IF actual IS DISTINCT FROM(SELECT snapshot FROM dabab_before) THEN RAISE EXCEPTION 'Protected data changed';END IF; IF EXISTS(SELECT cafe_id,to_jsonb(s)-'logo_storage_path'-'updated_at' FROM public.cafe_settings s WHERE cafe_id IN('3813425d-db13-4d30-8b82-9d41aad12e36') EXCEPT SELECT cafe_id,payload FROM dabab_settings_before) THEN RAISE EXCEPTION 'Non-logo settings changed';END IF; IF(SELECT count(*) FROM public.menu_products WHERE cafe_id IN('3813425d-db13-4d30-8b82-9d41aad12e36') AND available AND price>0)<>102 THEN RAISE EXCEPTION 'Public catalog count differs';END IF;IF(SELECT count(*) FROM public.menu_products WHERE cafe_id IN('3813425d-db13-4d30-8b82-9d41aad12e36') AND available AND image_storage_path IS NOT NULL)<>36 THEN RAISE EXCEPTION 'Reviewed source image count differs';END IF;END $verify$;
COMMIT;
